LIFECYCLE_CONTENT = 'from __future__ import annotations\n\nimport sqlite3\nfrom contextlib import contextmanager\nfrom dataclasses import dataclass\nfrom datetime import datetime, timezone\nfrom decimal import Decimal, InvalidOperation, localcontext\nfrom typing import Any, Iterator\nfrom uuid import uuid4\n\nfrom .catalog import HoldingsCatalog\nfrom .domain import HoldingPosition, HoldingPositionEvent\n\n\nclass HoldingsLifecycleError(RuntimeError):\n    def __init__(self, code: str, message: str):\n        super().__init__(message)\n        self.code = code\n        self.message = message\n\n\n@dataclass(frozen=True, slots=True)\nclass PositionLifecycleResult:\n    position: HoldingPosition\n    event: HoldingPositionEvent\n\n\ndef _now() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\n\ndef _decimal(value: Decimal | int | str, *, code: str, label: str) -> Decimal:\n    try:\n        number = value if isinstance(value, Decimal) else Decimal(str(value))\n    except (InvalidOperation, ValueError, TypeError) as exc:\n        raise HoldingsLifecycleError(code, f"{label} 값이 올바르지 않습니다.") from exc\n    if not number.is_finite():\n        raise HoldingsLifecycleError(code, f"{label}은 유한한 숫자여야 합니다.")\n    return number\n\n\ndef _positive_decimal(\n    value: Decimal | int | str,\n    *,\n    code: str,\n    label: str,\n) -> Decimal:\n    number = _decimal(value, code=code, label=label)\n    if number <= 0:\n        raise HoldingsLifecycleError(code, f"{label}은 0보다 커야 합니다.")\n    return number\n\n\ndef _non_negative_decimal(\n    value: Decimal | int | str,\n    *,\n    code: str,\n    label: str,\n) -> Decimal:\n    number = _decimal(value, code=code, label=label)\n    if number < 0:\n        raise HoldingsLifecycleError(code, f"{label}은 음수일 수 없습니다.")\n    return number\n\n\ndef _decimal_text(value: Decimal) -> str:\n    return format(value, "f")\n\n\ndef _parse_aware_datetime(value: str, *, code: str, label: str) -> datetime:\n    raw = (value or "").strip()\n    if not raw:\n        raise HoldingsLifecycleError(code, f"{label}이 필요합니다.")\n    normalized = raw[:-1] + "+00:00" if raw.endswith("Z") else raw\n    try:\n        parsed = datetime.fromisoformat(normalized)\n    except ValueError as exc:\n        raise HoldingsLifecycleError(\n            code,\n            f"{label}은 timezone이 포함된 ISO-8601 형식이어야 합니다.",\n        ) from exc\n    if parsed.tzinfo is None or parsed.utcoffset() is None:\n        raise HoldingsLifecycleError(\n            code,\n            f"{label}에는 timezone 정보가 필요합니다.",\n        )\n    return parsed\n\n\ndef _canonical_time(value: str, *, code: str, label: str) -> tuple[str, datetime]:\n    parsed = _parse_aware_datetime(value, code=code, label=label)\n    return parsed.isoformat(), parsed\n\n\nclass PositionLifecycleService:\n    """Manual/virtual position ledger with atomic Position + Event updates."""\n\n    def __init__(self, catalog: HoldingsCatalog):\n        self.catalog = catalog\n\n    @contextmanager\n    def _transaction(self) -> Iterator[sqlite3.Connection]:\n        conn = self.catalog.connect()\n        try:\n            conn.execute("BEGIN IMMEDIATE")\n            yield conn\n            conn.commit()\n        except Exception:\n            conn.rollback()\n            raise\n        finally:\n            conn.close()\n\n    @staticmethod\n    def _account_row(conn: sqlite3.Connection, account_id: str) -> sqlite3.Row:\n        row = conn.execute(\n            "SELECT * FROM position_account WHERE id=?",\n            (account_id,),\n        ).fetchone()\n        if row is None or str(row["status"]) != "ACTIVE":\n            raise HoldingsLifecycleError(\n                "HOLD_POSITION_ACCOUNT_NOT_FOUND",\n                "사용할 수 있는 Position 계좌를 찾을 수 없습니다.",\n            )\n        return row\n\n    @staticmethod\n    def _stock_row(conn: sqlite3.Connection, stock_id: str) -> sqlite3.Row:\n        row = conn.execute(\n            "SELECT * FROM monitored_stock WHERE id=?",\n            (stock_id,),\n        ).fetchone()\n        if row is None:\n            raise HoldingsLifecycleError(\n                "HOLD_POSITION_STOCK_NOT_FOUND",\n                "관리 대상 종목을 찾을 수 없습니다.",\n            )\n        return row\n\n    @staticmethod\n    def _assert_internal_account(account: sqlite3.Row) -> None:\n        if str(account["account_kind"]).upper() == "BROKER":\n            raise HoldingsLifecycleError(\n                "HOLD_POSITION_SOURCE_MANAGED_EXTERNALLY",\n                "증권사 계좌 Position은 수동 BUY/SELL/CORRECTION으로 변경할 수 없습니다.",\n            )\n\n    @staticmethod\n    def _opened_reason(account: sqlite3.Row) -> str:\n        kind = str(account["account_kind"]).upper()\n        if kind == "MANUAL":\n            return "MANUAL"\n        if kind == "VIRTUAL":\n            return "VIRTUAL"\n        raise HoldingsLifecycleError(\n            "HOLD_POSITION_SOURCE_MANAGED_EXTERNALLY",\n            "증권사 계좌 Position은 외부 잔고 동기화로만 변경합니다.",\n        )\n\n    @staticmethod\n    def _open_position_row(\n        conn: sqlite3.Connection,\n        stock_id: str,\n        account_id: str,\n    ) -> sqlite3.Row | None:\n        return conn.execute(\n            """\n            SELECT * FROM holding_position\n            WHERE monitored_stock_id=? AND position_account_id=? AND status=\'OPEN\'\n            """,\n            (stock_id, account_id),\n        ).fetchone()\n\n    @staticmethod\n    def _position_row(\n        conn: sqlite3.Connection,\n        position_id: str,\n    ) -> sqlite3.Row:\n        row = conn.execute(\n            "SELECT * FROM holding_position WHERE id=?",\n            (position_id,),\n        ).fetchone()\n        if row is None:\n            raise HoldingsLifecycleError(\n                "HOLD_POSITION_NOT_FOUND",\n                "Position을 찾을 수 없습니다.",\n            )\n        return row\n\n    @staticmethod\n    def _assert_open(position: sqlite3.Row) -> None:\n        if str(position["status"]).upper() != "OPEN":\n            raise HoldingsLifecycleError(\n                "HOLD_POSITION_ALREADY_CLOSED",\n                "이미 종료된 Position은 변경할 수 없습니다.",\n            )\n\n    @staticmethod\n    def _last_effective_at(\n        conn: sqlite3.Connection,\n        position_id: str,\n    ) -> datetime | None:\n        rows = conn.execute(\n            """\n            SELECT effective_at\n            FROM holding_position_event\n            WHERE position_id=? AND effective_at IS NOT NULL\n            """,\n            (position_id,),\n        ).fetchall()\n        latest: datetime | None = None\n        for row in rows:\n            raw = str(row["effective_at"] or "").strip()\n            if not raw:\n                continue\n            try:\n                parsed = _parse_aware_datetime(\n                    raw,\n                    code="HOLD_POSITION_CONFLICT",\n                    label="저장된 effective_at",\n                )\n            except HoldingsLifecycleError as exc:\n                raise HoldingsLifecycleError(\n                    "HOLD_POSITION_CONFLICT",\n                    "기존 Position Event의 시간이 올바르지 않아 안전하게 변경할 수 없습니다.",\n                ) from exc\n            absolute = parsed.astimezone(timezone.utc)\n            if latest is None or absolute > latest:\n                latest = absolute\n        return latest\n\n    @classmethod\n    def _assert_event_order(\n        cls,\n        conn: sqlite3.Connection,\n        position_id: str,\n        effective_at: datetime,\n    ) -> None:\n        latest = cls._last_effective_at(conn, position_id)\n        if latest is not None and effective_at.astimezone(timezone.utc) < latest:\n            raise HoldingsLifecycleError(\n                "HOLD_POSITION_EVENT_OUT_OF_ORDER",\n                "마지막 Position Event보다 과거 시각의 이벤트를 뒤늦게 삽입할 수 없습니다.",\n            )\n\n    @staticmethod\n    def _validate_revision(\n        conn: sqlite3.Connection,\n        *,\n        revision_id: str | None,\n        monitored_stock_id: str,\n        effective_at: datetime,\n    ) -> None:\n        if revision_id is None:\n            return\n        row = conn.execute(\n            """\n            SELECT r.id,r.computed_at,d.monitored_stock_id\n            FROM stock_analysis_revision r\n            JOIN stock_analysis_day d ON d.id=r.analysis_day_id\n            WHERE r.id=?\n            """,\n            (revision_id,),\n        ).fetchone()\n        if row is None or str(row["monitored_stock_id"]) != monitored_stock_id:\n            raise HoldingsLifecycleError(\n                "HOLD_POSITION_REVISION_MISMATCH",\n                "BUY 대상 종목과 Analysis Revision의 종목이 일치하지 않습니다.",\n            )\n        computed_at = _parse_aware_datetime(\n            str(row["computed_at"]),\n            code="HOLD_POSITION_CONFLICT",\n            label="Analysis Revision computed_at",\n        )\n        if computed_at.astimezone(timezone.utc) > effective_at.astimezone(timezone.utc):\n            raise HoldingsLifecycleError(\n                "HOLD_POSITION_REVISION_FROM_FUTURE",\n                "매수 시점 이후에 계산된 Analysis Revision은 매수 당시 분석으로 연결할 수 없습니다.",\n            )\n\n    @staticmethod\n    def _position_values(position: sqlite3.Row) -> tuple[Decimal, Decimal | None, Decimal]:\n        quantity = _non_negative_decimal(\n            str(position["current_quantity"]),\n            code="HOLD_POSITION_CONFLICT",\n            label="저장된 보유 수량",\n        )\n        average = (\n            None\n            if position["current_average_price"] is None\n            else _positive_decimal(\n                str(position["current_average_price"]),\n                code="HOLD_POSITION_CONFLICT",\n                label="저장된 평균단가",\n            )\n        )\n        if quantity > 0 and average is None:\n            raise HoldingsLifecycleError(\n                "HOLD_POSITION_CONFLICT",\n                "보유 수량이 있는데 평균단가가 없어 Position을 안전하게 변경할 수 없습니다.",\n            )\n        if position["current_cost_basis"] is not None:\n            cost = _non_negative_decimal(\n                str(position["current_cost_basis"]),\n                code="HOLD_POSITION_CONFLICT",\n                label="저장된 원금",\n            )\n        elif quantity == 0:\n            cost = Decimal("0")\n        else:\n            assert average is not None\n            cost = quantity * average\n        return quantity, average, cost\n\n    def _insert_event(\n        self,\n        conn: sqlite3.Connection,\n        *,\n        position_id: str,\n        event_type: str,\n        quantity_delta: Decimal,\n        unit_price: Decimal | None,\n        before_quantity: Decimal,\n        after_quantity: Decimal,\n        before_average_price: Decimal | None,\n        after_average_price: Decimal | None,\n        effective_at: str,\n        analysis_revision_id: str | None,\n        note: str | None,\n    ) -> HoldingPositionEvent:\n        event_id = str(uuid4())\n        now = _now()\n        conn.execute(\n            """\n            INSERT INTO holding_position_event(\n                id,position_id,event_type,quantity_delta,unit_price,\n                before_quantity,after_quantity,before_average_price,\n                after_average_price,observed_at,effective_at,\n                analysis_revision_id,account_sync_run_id,\n                external_event_key,note,created_at\n            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)\n            """,\n            (\n                event_id,\n                position_id,\n                event_type,\n                _decimal_text(quantity_delta),\n                _decimal_text(unit_price) if unit_price is not None else None,\n                _decimal_text(before_quantity),\n                _decimal_text(after_quantity),\n                _decimal_text(before_average_price)\n                if before_average_price is not None\n                else None,\n                _decimal_text(after_average_price)\n                if after_average_price is not None\n                else None,\n                None,\n                effective_at,\n                analysis_revision_id,\n                None,\n                None,\n                note,\n                now,\n            ),\n        )\n        row = conn.execute(\n            "SELECT * FROM holding_position_event WHERE id=?",\n            (event_id,),\n        ).fetchone()\n        return self.catalog._event_from_row(row)  # noqa: SLF001\n\n    def record_buy(\n        self,\n        *,\n        monitored_stock_id: str,\n        position_account_id: str,\n        quantity: Decimal | int | str,\n        unit_price: Decimal | int | str,\n        effective_at: str,\n        analysis_revision_id: str | None = None,\n        note: str | None = None,\n    ) -> PositionLifecycleResult:\n        buy_quantity = _positive_decimal(\n            quantity,\n            code="HOLD_POSITION_QUANTITY_INVALID",\n            label="매수 수량",\n        )\n        buy_price = _positive_decimal(\n            unit_price,\n            code="HOLD_POSITION_PRICE_INVALID",\n            label="매수가격",\n        )\n        effective_text, effective_dt = _canonical_time(\n            effective_at,\n            code="HOLD_POSITION_TIME_INVALID",\n            label="effective_at",\n        )\n\n        try:\n            with self._transaction() as conn:\n                self._stock_row(conn, monitored_stock_id)\n                account = self._account_row(conn, position_account_id)\n                self._assert_internal_account(account)\n                self._validate_revision(\n                    conn,\n                    revision_id=analysis_revision_id,\n                    monitored_stock_id=monitored_stock_id,\n                    effective_at=effective_dt,\n                )\n\n                position = self._open_position_row(\n                    conn,\n                    monitored_stock_id,\n                    position_account_id,\n                )\n                now = _now()\n                if position is None:\n                    position_id = str(uuid4())\n                    before_quantity = Decimal("0")\n                    before_average = None\n                    after_quantity = buy_quantity\n                    after_average = buy_price\n                    after_cost = buy_quantity * buy_price\n                    conn.execute(\n                        """\n                        INSERT INTO holding_position(\n                            id,monitored_stock_id,position_account_id,status,\n                            opened_at,closed_at,current_quantity,current_average_price,\n                            current_cost_basis,opened_reason,last_observed_at,last_sync_run_id,\n                            created_at,updated_at\n                        ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)\n                        """,\n                        (\n                            position_id,\n                            monitored_stock_id,\n                            position_account_id,\n                            "OPEN",\n                            effective_text,\n                            None,\n                            _decimal_text(after_quantity),\n                            _decimal_text(after_average),\n                            _decimal_text(after_cost),\n                            self._opened_reason(account),\n                            None,\n                            None,\n                            now,\n                            now,\n                        ),\n                    )\n                else:\n                    self._assert_open(position)\n                    position_id = str(position["id"])\n                    self._assert_event_order(conn, position_id, effective_dt)\n                    before_quantity, before_average, before_cost = self._position_values(\n                        position\n                    )\n                    after_quantity = before_quantity + buy_quantity\n                    with localcontext() as context:\n                        context.prec = 50\n                        after_cost = before_cost + buy_quantity * buy_price\n                        after_average = after_cost / after_quantity\n                    cursor = conn.execute(\n                        """\n                        UPDATE holding_position\n                        SET current_quantity=?,current_average_price=?,\n                            current_cost_basis=?,updated_at=?\n                        WHERE id=? AND status=\'OPEN\'\n                        """,\n                        (\n                            _decimal_text(after_quantity),\n                            _decimal_text(after_average),\n                            _decimal_text(after_cost),\n                            now,\n                            position_id,\n                        ),\n                    )\n                    if cursor.rowcount != 1:\n                        raise HoldingsLifecycleError(\n                            "HOLD_POSITION_CONFLICT",\n                            "Position이 동시에 변경되어 BUY를 적용하지 못했습니다.",\n                        )\n\n                event = self._insert_event(\n                    conn,\n                    position_id=position_id,\n                    event_type="BUY",\n                    quantity_delta=buy_quantity,\n                    unit_price=buy_price,\n                    before_quantity=before_quantity,\n                    after_quantity=after_quantity,\n                    before_average_price=before_average,\n                    after_average_price=after_average,\n                    effective_at=effective_text,\n                    analysis_revision_id=analysis_revision_id,\n                    note=note,\n                )\n                stored = conn.execute(\n                    "SELECT * FROM holding_position WHERE id=?",\n                    (position_id,),\n                ).fetchone()\n                result = PositionLifecycleResult(\n                    position=self.catalog._position_from_row(stored),  # noqa: SLF001\n                    event=event,\n                )\n        except sqlite3.IntegrityError as exc:\n            raise HoldingsLifecycleError(\n                "HOLD_POSITION_CONFLICT",\n                "BUY 저장 중 Position 원장 충돌이 발생했습니다.",\n            ) from exc\n        return result\n\n    def record_sell(\n        self,\n        *,\n        position_id: str,\n        quantity: Decimal | int | str,\n        unit_price: Decimal | int | str,\n        effective_at: str,\n        note: str | None = None,\n    ) -> PositionLifecycleResult:\n        sell_quantity = _positive_decimal(\n            quantity,\n            code="HOLD_POSITION_QUANTITY_INVALID",\n            label="매도 수량",\n        )\n        sell_price = _positive_decimal(\n            unit_price,\n            code="HOLD_POSITION_PRICE_INVALID",\n            label="매도가격",\n        )\n        effective_text, effective_dt = _canonical_time(\n            effective_at,\n            code="HOLD_POSITION_TIME_INVALID",\n            label="effective_at",\n        )\n\n        try:\n            with self._transaction() as conn:\n                position = self._position_row(conn, position_id)\n                self._assert_open(position)\n                account = self._account_row(\n                    conn,\n                    str(position["position_account_id"]),\n                )\n                self._assert_internal_account(account)\n                self._assert_event_order(conn, position_id, effective_dt)\n\n                before_quantity, before_average, _ = self._position_values(position)\n                if sell_quantity > before_quantity:\n                    raise HoldingsLifecycleError(\n                        "HOLD_POSITION_SELL_EXCEEDS_HOLDING",\n                        "현재 보유 수량보다 많이 매도할 수 없습니다.",\n                    )\n                if before_average is None:\n                    raise HoldingsLifecycleError(\n                        "HOLD_POSITION_CONFLICT",\n                        "평균단가가 없어 SELL을 안전하게 적용할 수 없습니다.",\n                    )\n\n                after_quantity = before_quantity - sell_quantity\n                after_average = before_average\n                after_cost = (\n                    Decimal("0")\n                    if after_quantity == 0\n                    else after_quantity * before_average\n                )\n                now = _now()\n                status = "CLOSED" if after_quantity == 0 else "OPEN"\n                closed_at = effective_text if after_quantity == 0 else None\n                cursor = conn.execute(\n                    """\n                    UPDATE holding_position\n                    SET status=?,closed_at=?,current_quantity=?,\n                        current_average_price=?,current_cost_basis=?,updated_at=?\n                    WHERE id=? AND status=\'OPEN\'\n                    """,\n                    (\n                        status,\n                        closed_at,\n                        _decimal_text(after_quantity),\n                        _decimal_text(after_average),\n                        _decimal_text(after_cost),\n                        now,\n                        position_id,\n                    ),\n                )\n                if cursor.rowcount != 1:\n                    raise HoldingsLifecycleError(\n                        "HOLD_POSITION_CONFLICT",\n                        "Position이 동시에 변경되어 SELL을 적용하지 못했습니다.",\n                    )\n\n                event = self._insert_event(\n                    conn,\n                    position_id=position_id,\n                    event_type="SELL",\n                    quantity_delta=-sell_quantity,\n                    unit_price=sell_price,\n                    before_quantity=before_quantity,\n                    after_quantity=after_quantity,\n                    before_average_price=before_average,\n                    after_average_price=after_average,\n                    effective_at=effective_text,\n                    analysis_revision_id=None,\n                    note=note,\n                )\n                stored = conn.execute(\n                    "SELECT * FROM holding_position WHERE id=?",\n                    (position_id,),\n                ).fetchone()\n                result = PositionLifecycleResult(\n                    position=self.catalog._position_from_row(stored),  # noqa: SLF001\n                    event=event,\n                )\n        except sqlite3.IntegrityError as exc:\n            raise HoldingsLifecycleError(\n                "HOLD_POSITION_CONFLICT",\n                "SELL 저장 중 Position 원장 충돌이 발생했습니다.",\n            ) from exc\n        return result\n\n    def record_correction(\n        self,\n        *,\n        position_id: str,\n        corrected_quantity: Decimal | int | str,\n        corrected_average_price: Decimal | int | str,\n        effective_at: str,\n        note: str,\n    ) -> PositionLifecycleResult:\n        correction_note = (note or "").strip()\n        if not correction_note:\n            raise HoldingsLifecycleError(\n                "HOLD_POSITION_CORRECTION_NOTE_REQUIRED",\n                "CORRECTION에는 수정 사유가 필요합니다.",\n            )\n        after_quantity = _non_negative_decimal(\n            corrected_quantity,\n            code="HOLD_POSITION_QUANTITY_INVALID",\n            label="수정 수량",\n        )\n        after_average = _positive_decimal(\n            corrected_average_price,\n            code="HOLD_POSITION_PRICE_INVALID",\n            label="수정 평균단가",\n        )\n        effective_text, effective_dt = _canonical_time(\n            effective_at,\n            code="HOLD_POSITION_TIME_INVALID",\n            label="effective_at",\n        )\n\n        try:\n            with self._transaction() as conn:\n                position = self._position_row(conn, position_id)\n                self._assert_open(position)\n                account = self._account_row(\n                    conn,\n                    str(position["position_account_id"]),\n                )\n                self._assert_internal_account(account)\n                self._assert_event_order(conn, position_id, effective_dt)\n\n                before_quantity, before_average, _ = self._position_values(position)\n                after_cost = (\n                    Decimal("0")\n                    if after_quantity == 0\n                    else after_quantity * after_average\n                )\n                status = "CLOSED" if after_quantity == 0 else "OPEN"\n                closed_at = effective_text if after_quantity == 0 else None\n                now = _now()\n                cursor = conn.execute(\n                    """\n                    UPDATE holding_position\n                    SET status=?,closed_at=?,current_quantity=?,\n                        current_average_price=?,current_cost_basis=?,updated_at=?\n                    WHERE id=? AND status=\'OPEN\'\n                    """,\n                    (\n                        status,\n                        closed_at,\n                        _decimal_text(after_quantity),\n                        _decimal_text(after_average),\n                        _decimal_text(after_cost),\n                        now,\n                        position_id,\n                    ),\n                )\n                if cursor.rowcount != 1:\n                    raise HoldingsLifecycleError(\n                        "HOLD_POSITION_CONFLICT",\n                        "Position이 동시에 변경되어 CORRECTION을 적용하지 못했습니다.",\n                    )\n\n                event = self._insert_event(\n                    conn,\n                    position_id=position_id,\n                    event_type="CORRECTION",\n                    quantity_delta=after_quantity - before_quantity,\n                    unit_price=None,\n                    before_quantity=before_quantity,\n                    after_quantity=after_quantity,\n                    before_average_price=before_average,\n                    after_average_price=after_average,\n                    effective_at=effective_text,\n                    analysis_revision_id=None,\n                    note=correction_note,\n                )\n                stored = conn.execute(\n                    "SELECT * FROM holding_position WHERE id=?",\n                    (position_id,),\n                ).fetchone()\n                result = PositionLifecycleResult(\n                    position=self.catalog._position_from_row(stored),  # noqa: SLF001\n                    event=event,\n                )\n        except sqlite3.IntegrityError as exc:\n            raise HoldingsLifecycleError(\n                "HOLD_POSITION_CONFLICT",\n                "CORRECTION 저장 중 Position 원장 충돌이 발생했습니다.",\n            ) from exc\n        return result\n'
TEST_CONTENT = 'from __future__ import annotations\n\nimport sqlite3\nfrom decimal import Decimal\nfrom pathlib import Path\n\nimport pytest\n\nfrom app.holdings import (\n    HoldingsCatalog,\n    HoldingsLifecycleError,\n    PositionLifecycleService,\n)\n\n\nT0 = "2026-09-18T09:00:00+09:00"\nT1 = "2026-09-18T10:00:00+09:00"\nT2 = "2026-09-18T11:00:00+09:00"\nT3 = "2026-09-18T12:00:00+09:00"\nT4 = "2026-09-18T13:00:00+09:00"\n\n\n@pytest.fixture()\ndef env(tmp_path):\n    catalog = HoldingsCatalog(tmp_path / "holdings.db")\n    catalog.initialize()\n    service = PositionLifecycleService(catalog)\n    return catalog, service\n\n\ndef _manual_account(catalog: HoldingsCatalog):\n    return catalog.create_position_account(\n        provider="MANUAL",\n        account_kind="MANUAL",\n        display_name="수동 계좌",\n    )\n\n\ndef _virtual_account(catalog: HoldingsCatalog):\n    return catalog.create_position_account(\n        provider="VIRTUAL",\n        account_kind="VIRTUAL",\n        display_name="가상 계좌",\n    )\n\n\ndef _broker_account(catalog: HoldingsCatalog):\n    return catalog.create_position_account(\n        provider="KIS",\n        account_kind="BROKER",\n        broker_environment="REAL",\n        external_account_fingerprint="a" * 64,\n        display_name="KIS 실계좌",\n    )\n\n\ndef _stock(\n    catalog: HoldingsCatalog,\n    ticker: str = "005930",\n    name: str = "삼성전자",\n    *,\n    watch_enabled: bool = True,\n):\n    return catalog.create_monitored_stock(\n        market="KOSPI",\n        ticker=ticker,\n        name=name,\n        watch_enabled=watch_enabled,\n    )\n\n\ndef _revision(\n    catalog: HoldingsCatalog,\n    stock_id: str,\n    *,\n    fingerprint: str,\n    computed_at: str,\n):\n    day = catalog.get_or_create_analysis_day(\n        monitored_stock_id=stock_id,\n        market_date="2026-09-18",\n    )\n    revision = catalog.append_analysis_revision(\n        analysis_day_id=day.id,\n        input_fingerprint=fingerprint,\n        strategy_key="ma20_rebound",\n        action_state="WATCH",\n        risk_state="READY",\n        reference_price="261000",\n        stop_price="254124.8",\n        target1_price="271000",\n        target2_price="274750.4",\n        scanner_version="0.21.3.7",\n        analysis_engine_version="HOLD_SINGLE_STOCK_V1",\n        policy_version="TEST",\n        source_versions={"market_store": "fixture"},\n        snapshot={"strategy": "ma20_rebound"},\n        computed_at=computed_at,\n    )\n    return day, revision\n\n\ndef _schema_snapshot(catalog: HoldingsCatalog):\n    with catalog.connection() as conn:\n        rows = conn.execute(\n            """\n            SELECT type,name,sql\n            FROM sqlite_master\n            WHERE type IN (\'table\',\'index\',\'trigger\')\n            ORDER BY type,name\n            """\n        ).fetchall()\n    return [(row["type"], row["name"], row["sql"]) for row in rows]\n\n\ndef test_first_and_additional_buy_use_one_position_and_decimal_moving_average(env):\n    catalog, service = env\n    account = _manual_account(catalog)\n    stock = _stock(catalog, watch_enabled=False)\n\n    first = service.record_buy(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        quantity="10",\n        unit_price="70000",\n        effective_at=T1,\n    )\n    second = service.record_buy(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        quantity="5",\n        unit_price="80000",\n        effective_at=T2,\n    )\n\n    assert second.position.id == first.position.id\n    assert second.position.status == "OPEN"\n    assert second.position.current_quantity == Decimal("15")\n    assert second.position.current_cost_basis == Decimal("1100000")\n    with __import__("decimal").localcontext() as context:\n        context.prec = 50\n        expected_average = Decimal("1100000") / Decimal("15")\n    assert second.position.current_average_price == expected_average\n    assert catalog.get_monitored_stock(stock.id).watch_enabled is False\n\n    events = catalog.list_position_events(first.position.id)\n    assert [event.event_type for event in events] == ["BUY", "BUY"]\n    assert events[0].before_quantity == Decimal("0")\n    assert events[0].after_quantity == Decimal("10")\n    assert events[1].before_quantity == Decimal("10")\n    assert events[1].after_quantity == Decimal("15")\n\n\ndef test_virtual_buy_uses_virtual_open_reason(env):\n    catalog, service = env\n    account = _virtual_account(catalog)\n    stock = _stock(catalog)\n\n    result = service.record_buy(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        quantity="2",\n        unit_price="12345",\n        effective_at=T1,\n    )\n    assert result.position.opened_reason == "VIRTUAL"\n\n\ndef test_partial_sell_keeps_average_full_sell_closes_and_rebuy_starts_new_episode(env):\n    catalog, service = env\n    account = _manual_account(catalog)\n    stock = _stock(catalog)\n\n    opened = service.record_buy(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        quantity="15",\n        unit_price="73333.333333333333333333333333333333333333333333333333",\n        effective_at=T1,\n    )\n    original_average = opened.position.current_average_price\n\n    partial = service.record_sell(\n        position_id=opened.position.id,\n        quantity="5",\n        unit_price="85000",\n        effective_at=T2,\n    )\n    assert partial.position.status == "OPEN"\n    assert partial.position.current_quantity == Decimal("10")\n    assert partial.position.current_average_price == original_average\n    assert partial.position.current_cost_basis == Decimal("10") * original_average\n\n    closed = service.record_sell(\n        position_id=opened.position.id,\n        quantity="10",\n        unit_price="86000",\n        effective_at=T3,\n    )\n    assert closed.position.status == "CLOSED"\n    assert closed.position.current_quantity == Decimal("0")\n    assert closed.position.current_cost_basis == Decimal("0")\n    assert closed.position.current_average_price == original_average\n    assert closed.position.closed_at == T3\n\n    with pytest.raises(HoldingsLifecycleError) as exc_info:\n        service.record_sell(\n            position_id=opened.position.id,\n            quantity="1",\n            unit_price="87000",\n            effective_at=T4,\n        )\n    assert exc_info.value.code == "HOLD_POSITION_ALREADY_CLOSED"\n\n    rebuy = service.record_buy(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        quantity="3",\n        unit_price="80000",\n        effective_at=T4,\n    )\n    assert rebuy.position.id != opened.position.id\n    assert rebuy.position.status == "OPEN"\n    positions = catalog.list_positions(stock.id)\n    assert [item.status for item in positions] == ["CLOSED", "OPEN"]\n\n\ndef test_oversell_rolls_back_without_event_or_position_change(env):\n    catalog, service = env\n    account = _manual_account(catalog)\n    stock = _stock(catalog)\n    opened = service.record_buy(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        quantity="10",\n        unit_price="70000",\n        effective_at=T1,\n    )\n    before = catalog.get_position(opened.position.id)\n    events_before = catalog.list_position_events(opened.position.id)\n\n    with pytest.raises(HoldingsLifecycleError) as exc_info:\n        service.record_sell(\n            position_id=opened.position.id,\n            quantity="11",\n            unit_price="71000",\n            effective_at=T2,\n        )\n    assert exc_info.value.code == "HOLD_POSITION_SELL_EXCEEDS_HOLDING"\n\n    after = catalog.get_position(opened.position.id)\n    events_after = catalog.list_position_events(opened.position.id)\n    assert after == before\n    assert events_after == events_before\n\n\ndef test_correction_updates_snapshot_and_zero_closes_without_becoming_sell(env):\n    catalog, service = env\n    account = _manual_account(catalog)\n    stock = _stock(catalog)\n    opened = service.record_buy(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        quantity="10",\n        unit_price="70000",\n        effective_at=T1,\n    )\n\n    corrected = service.record_correction(\n        position_id=opened.position.id,\n        corrected_quantity="12",\n        corrected_average_price="71500",\n        effective_at=T2,\n        note="초기 입력 수량을 실제 잔고에 맞게 수정",\n    )\n    assert corrected.position.current_quantity == Decimal("12")\n    assert corrected.position.current_average_price == Decimal("71500")\n    assert corrected.position.current_cost_basis == Decimal("858000")\n    assert corrected.event.event_type == "CORRECTION"\n    assert corrected.event.quantity_delta == Decimal("2")\n\n    zeroed = service.record_correction(\n        position_id=opened.position.id,\n        corrected_quantity="0",\n        corrected_average_price="71500",\n        effective_at=T3,\n        note="실제 보유 없음으로 원장 수정",\n    )\n    assert zeroed.position.status == "CLOSED"\n    assert zeroed.position.current_quantity == Decimal("0")\n    assert zeroed.position.current_cost_basis == Decimal("0")\n    assert zeroed.position.current_average_price == Decimal("71500")\n    assert zeroed.event.event_type == "CORRECTION"\n    assert [e.event_type for e in catalog.list_position_events(opened.position.id)] == [\n        "BUY",\n        "CORRECTION",\n        "CORRECTION",\n    ]\n\n\ndef test_correction_requires_note_and_keeps_state_on_failure(env):\n    catalog, service = env\n    account = _manual_account(catalog)\n    stock = _stock(catalog)\n    opened = service.record_buy(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        quantity="10",\n        unit_price="70000",\n        effective_at=T1,\n    )\n\n    with pytest.raises(HoldingsLifecycleError) as exc_info:\n        service.record_correction(\n            position_id=opened.position.id,\n            corrected_quantity="12",\n            corrected_average_price="71000",\n            effective_at=T2,\n            note="   ",\n        )\n    assert exc_info.value.code == "HOLD_POSITION_CORRECTION_NOTE_REQUIRED"\n    assert catalog.get_position(opened.position.id) == opened.position\n    assert len(catalog.list_position_events(opened.position.id)) == 1\n\n\ndef test_event_time_must_be_timezone_aware_and_not_go_backwards(env):\n    catalog, service = env\n    account = _manual_account(catalog)\n    stock = _stock(catalog)\n\n    with pytest.raises(HoldingsLifecycleError) as exc_info:\n        service.record_buy(\n            monitored_stock_id=stock.id,\n            position_account_id=account.id,\n            quantity="1",\n            unit_price="70000",\n            effective_at="2026-09-18T10:00:00",\n        )\n    assert exc_info.value.code == "HOLD_POSITION_TIME_INVALID"\n\n    opened = service.record_buy(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        quantity="10",\n        unit_price="70000",\n        effective_at=T2,\n    )\n    with pytest.raises(HoldingsLifecycleError) as exc_info:\n        service.record_sell(\n            position_id=opened.position.id,\n            quantity="1",\n            unit_price="71000",\n            effective_at=T1,\n        )\n    assert exc_info.value.code == "HOLD_POSITION_EVENT_OUT_OF_ORDER"\n    assert catalog.get_position(opened.position.id).current_quantity == Decimal("10")\n    assert len(catalog.list_position_events(opened.position.id)) == 1\n\n\ndef test_broker_position_is_externally_managed_for_buy_sell_and_correction(env):\n    catalog, service = env\n    account = _broker_account(catalog)\n    stock = _stock(catalog)\n\n    with pytest.raises(HoldingsLifecycleError) as exc_info:\n        service.record_buy(\n            monitored_stock_id=stock.id,\n            position_account_id=account.id,\n            quantity="1",\n            unit_price="70000",\n            effective_at=T1,\n        )\n    assert exc_info.value.code == "HOLD_POSITION_SOURCE_MANAGED_EXTERNALLY"\n    assert catalog.list_positions(stock.id) == []\n\n    observed = catalog.open_position(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        opened_reason="KIS_OBSERVED",\n        opened_at=T0,\n        current_quantity="10",\n        current_average_price="70000",\n        current_cost_basis="700000",\n    )\n    with pytest.raises(HoldingsLifecycleError) as sell_exc:\n        service.record_sell(\n            position_id=observed.id,\n            quantity="1",\n            unit_price="71000",\n            effective_at=T1,\n        )\n    assert sell_exc.value.code == "HOLD_POSITION_SOURCE_MANAGED_EXTERNALLY"\n\n    with pytest.raises(HoldingsLifecycleError) as correction_exc:\n        service.record_correction(\n            position_id=observed.id,\n            corrected_quantity="9",\n            corrected_average_price="70000",\n            effective_at=T1,\n            note="test",\n        )\n    assert correction_exc.value.code == "HOLD_POSITION_SOURCE_MANAGED_EXTERNALLY"\n\n\ndef test_buy_revision_must_match_stock_and_exist_before_buy(env):\n    catalog, service = env\n    account = _manual_account(catalog)\n    stock = _stock(catalog)\n    other = _stock(catalog, "000660", "SK하이닉스")\n\n    day, good = _revision(\n        catalog,\n        stock.id,\n        fingerprint="good",\n        computed_at="2026-09-18T08:30:00+09:00",\n    )\n    bought = service.record_buy(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        quantity="1",\n        unit_price="261000",\n        effective_at=T1,\n        analysis_revision_id=good.id,\n    )\n    assert bought.event.analysis_revision_id == good.id\n\n    later = catalog.append_analysis_revision(\n        analysis_day_id=day.id,\n        input_fingerprint="later-current",\n        strategy_key="trend_following",\n        action_state="READY",\n        risk_state="READY",\n        reference_price="262000",\n        stop_price=None,\n        target1_price=None,\n        target2_price=None,\n        scanner_version="0.21.3.7",\n        analysis_engine_version="HOLD_SINGLE_STOCK_V1",\n        policy_version="TEST",\n        source_versions={},\n        snapshot={},\n        computed_at="2026-09-18T10:30:00+09:00",\n    )\n    catalog.promote_current_revision(\n        analysis_day_id=day.id,\n        revision_id=later.id,\n    )\n    assert catalog.list_position_events(bought.position.id)[0].analysis_revision_id == good.id\n\n    _, wrong_stock = _revision(\n        catalog,\n        other.id,\n        fingerprint="wrong-stock",\n        computed_at="2026-09-18T08:00:00+09:00",\n    )\n    account2 = catalog.create_position_account(\n        provider="MANUAL",\n        account_kind="MANUAL",\n        display_name="수동 계좌 2",\n    )\n    with pytest.raises(HoldingsLifecycleError) as mismatch_exc:\n        service.record_buy(\n            monitored_stock_id=stock.id,\n            position_account_id=account2.id,\n            quantity="1",\n            unit_price="261000",\n            effective_at=T1,\n            analysis_revision_id=wrong_stock.id,\n        )\n    assert mismatch_exc.value.code == "HOLD_POSITION_REVISION_MISMATCH"\n\n    future_day, future_revision = _revision(\n        catalog,\n        stock.id,\n        fingerprint="future",\n        computed_at="2026-09-18T12:00:00+09:00",\n    )\n    assert future_day.id == day.id\n    with pytest.raises(HoldingsLifecycleError) as future_exc:\n        service.record_buy(\n            monitored_stock_id=stock.id,\n            position_account_id=account2.id,\n            quantity="1",\n            unit_price="261000",\n            effective_at=T1,\n            analysis_revision_id=future_revision.id,\n        )\n    assert future_exc.value.code == "HOLD_POSITION_REVISION_FROM_FUTURE"\n    assert catalog.list_positions(stock.id, status="OPEN") == [bought.position]\n\n\ndef test_position_and_event_are_one_atomic_transaction(env, monkeypatch):\n    catalog, service = env\n    account = _manual_account(catalog)\n    stock = _stock(catalog)\n    opened = service.record_buy(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        quantity="10",\n        unit_price="70000",\n        effective_at=T1,\n    )\n    before = catalog.get_position(opened.position.id)\n    events_before = catalog.list_position_events(opened.position.id)\n\n    def fail_event(*args, **kwargs):\n        raise RuntimeError("forced event failure")\n\n    monkeypatch.setattr(service, "_insert_event", fail_event)\n    with pytest.raises(RuntimeError, match="forced event failure"):\n        service.record_buy(\n            monitored_stock_id=stock.id,\n            position_account_id=account.id,\n            quantity="5",\n            unit_price="80000",\n            effective_at=T2,\n        )\n\n    assert catalog.get_position(opened.position.id) == before\n    assert catalog.list_position_events(opened.position.id) == events_before\n\n\ndef test_quantity_and_price_validation(env):\n    catalog, service = env\n    account = _manual_account(catalog)\n    stock = _stock(catalog)\n\n    for quantity in ("0", "-1"):\n        with pytest.raises(HoldingsLifecycleError) as exc_info:\n            service.record_buy(\n                monitored_stock_id=stock.id,\n                position_account_id=account.id,\n                quantity=quantity,\n                unit_price="70000",\n                effective_at=T1,\n            )\n        assert exc_info.value.code == "HOLD_POSITION_QUANTITY_INVALID"\n\n    with pytest.raises(HoldingsLifecycleError) as exc_info:\n        service.record_buy(\n            monitored_stock_id=stock.id,\n            position_account_id=account.id,\n            quantity="1",\n            unit_price="0",\n            effective_at=T1,\n        )\n    assert exc_info.value.code == "HOLD_POSITION_PRICE_INVALID"\n\n\ndef test_lifecycle_does_not_change_schema_or_depend_on_scanner_kis_or_analysis(env):\n    catalog, service = env\n    before = _schema_snapshot(catalog)\n    account = _manual_account(catalog)\n    stock = _stock(catalog)\n    service.record_buy(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        quantity="1",\n        unit_price="70000",\n        effective_at=T1,\n    )\n    after = _schema_snapshot(catalog)\n    assert after == before\n\n    source = Path("backend/app/holdings/lifecycle.py").read_text(encoding="utf-8")\n    assert "integrations.kis" not in source\n    assert "app.backtest" not in source\n    assert "analysis.py" not in source\n    assert "float(" not in source\n'
INIT_APPEND = '\nfrom .lifecycle import (\n    HoldingsLifecycleError,\n    PositionLifecycleResult,\n    PositionLifecycleService,\n)\n\n__all__.extend(\n    [\n        "HoldingsLifecycleError",\n        "PositionLifecycleResult",\n        "PositionLifecycleService",\n    ]\n)\n'


def fail(message: str) -> None:
    raise RuntimeError(message)


def run(cmd: list[str], label: str) -> None:
    print()
    print(f"=== {label} ===")
    print(" ".join(cmd))
    result = subprocess.run(cmd, cwd=ROOT)
    if result.returncode != 0:
        fail(f"{label} failed with exit code {result.returncode}")


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def source_tree_hash(path: Path) -> str:
    hasher = hashlib.sha256()
    if not path.exists():
        return "MISSING"
    files = [path] if path.is_file() else sorted(
        item for item in path.rglob("*.py")
        if "__pycache__" not in item.parts
    )
    for item in files:
        hasher.update(str(item.relative_to(ROOT)).replace("\\", "/").encode("utf-8"))
        hasher.update(b"\0")
        hasher.update(item.read_bytes())
        hasher.update(b"\0")
    return hasher.hexdigest()


def main() -> int:
    print("PROJECT ROOT:", ROOT)
    print("HOLD.1-C Position Lifecycle")
    print("Scope: MANUAL / VIRTUAL BUY, SELL, CORRECTION")
    print("KIS/BROKER manual mutation: FORBIDDEN")
    print("DB schema change: NO")
    print("Scanner/Strategy/Risk/KIS modification: NO")

    for required in (CATALOG, DOMAIN, ANALYSIS, INIT):
        if not required.is_file():
            fail(f"Required file missing: {required}")
    for target in (LIFECYCLE, TEST):
        if target.exists():
            fail(f"Target already exists: {target}")

    catalog_text = CATALOG.read_text(encoding="utf-8-sig")
    init_text = INIT.read_text(encoding="utf-8-sig")
    required_catalog_markers = [
        "def connection(self)",
        "CREATE TABLE IF NOT EXISTS holding_position (",
        "CREATE TABLE IF NOT EXISTS holding_position_event (",
        "CREATE TABLE IF NOT EXISTS stock_analysis_revision (",
        "trg_holding_position_event_no_update",
        "trg_holding_position_event_no_delete",
    ]
    missing = [marker for marker in required_catalog_markers if marker not in catalog_text]
    if missing:
        print()
        print("C.0 SOURCE AUDIT: STOP")
        print("Unexpected local HOLD.1-A catalog; no files were changed.")
        print("Missing markers:", missing)
        return 2
    if "from .analysis import (" not in init_text:
        print()
        print("C.0 SOURCE AUDIT: STOP")
        print("HOLD.1-B exports were not found; no files were changed.")
        return 2

    protected = {
        "catalog.py": sha256(CATALOG),
        "domain.py": sha256(DOMAIN),
        "analysis.py": sha256(ANALYSIS),
        "scanner.py": source_tree_hash(ROOT / "backend" / "app" / "backtest" / "scanner.py"),
        "strategy": source_tree_hash(ROOT / "backend" / "app" / "strategy"),
        "risk": source_tree_hash(ROOT / "backend" / "app" / "risk"),
        "kis": source_tree_hash(ROOT / "backend" / "app" / "integrations" / "kis"),
    }

    compile(LIFECYCLE_CONTENT, str(LIFECYCLE), "exec")
    compile(TEST_CONTENT, str(TEST), "exec")

    init_before = init_text
    created = []
    init_changed = False
    try:
        LIFECYCLE.write_text(LIFECYCLE_CONTENT, encoding="utf-8", newline="\n")
        created.append(LIFECYCLE)
        TEST.write_text(TEST_CONTENT, encoding="utf-8", newline="\n")
        created.append(TEST)

        if "from .lifecycle import (" in init_text:
            fail("holdings/__init__.py already contains lifecycle exports.")
        INIT.write_text(
            init_text.rstrip() + "\n" + INIT_APPEND.lstrip(),
            encoding="utf-8",
            newline="\n",
        )
        init_changed = True

        venv_python = ROOT / ".venv" / "Scripts" / "python.exe"
        python_exe = str(
            venv_python if venv_python.is_file() else Path(sys.executable)
        )

        run(
            [
                python_exe,
                "-m",
                "pytest",
                "backend/tests/test_holdings_lifecycle_hold1c.py",
                "-q",
            ],
            "HOLD.1-C lifecycle tests",
        )

        run(
            [
                python_exe,
                "-m",
                "pytest",
                "backend/tests/test_holdings_catalog_hold1a.py",
                "backend/tests/test_holdings_analysis_hold1b.py",
                "-q",
            ],
            "HOLD.1-A + HOLD.1-B regression",
        )

        after = {
            "catalog.py": sha256(CATALOG),
            "domain.py": sha256(DOMAIN),
            "analysis.py": sha256(ANALYSIS),
            "scanner.py": source_tree_hash(ROOT / "backend" / "app" / "backtest" / "scanner.py"),
            "strategy": source_tree_hash(ROOT / "backend" / "app" / "strategy"),
            "risk": source_tree_hash(ROOT / "backend" / "app" / "risk"),
            "kis": source_tree_hash(ROOT / "backend" / "app" / "integrations" / "kis"),
        }
        changed = [name for name in protected if protected[name] != after[name]]
        if changed:
            fail("Protected source changed during HOLD.1-C: " + ", ".join(changed))

        print()
        print("HOLD.1-C CLOSED")
        print("Added:")
        print(" - backend/app/holdings/lifecycle.py")
        print(" - backend/tests/test_holdings_lifecycle_hold1c.py")
        print("Modified:")
        print(" - backend/app/holdings/__init__.py (exports only)")
        print("BUY moving-average lifecycle: PASS")
        print("Partial/full SELL lifecycle: PASS")
        print("CLOSED -> repurchase new episode: PASS")
        print("CORRECTION lifecycle: PASS")
        print("Timezone/order guard: PASS")
        print("Analysis Revision stock/time guard: PASS")
        print("BROKER manual mutation blocked: PASS")
        print("Position + Event atomic transaction: PASS")
        print("Decimal-only ledger math: PASS")
        print("DB schema changed: NO")
        print("HOLD.1-A regression: PASS")
        print("HOLD.1-B regression: PASS")
        print("Scanner/Strategy/Risk/KIS changed: NO")
        return 0

    except Exception:
        if init_changed:
            INIT.write_text(init_before, encoding="utf-8", newline="\n")
        for path in reversed(created):
            if path.exists():
                path.unlink()
        print()
        print("FAILED — HOLD.1-C additions were rolled back.")
        print("catalog/domain/analysis/scanner/strategy/risk/KIS were not intentionally modified.")
        raise


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print()
        print(f"ERROR: {exc}", file=sys.stderr)
        raise SystemExit(1)
